export function renderClinician(state, { icon, escapeHTML:e, passportHTML, medicineLinkHTML, nursingRecordHTML }) {
 const doctorRequests=state.requests.filter(r=>r.route==='Doctor');
 const pending=doctorRequests.filter(r=>r.status==='Pending');
 const list=doctorRequests.filter(r=>state.filter==='Completed'?r.status!=='Pending':r.status==='Pending'&&(state.filter==='Pending'||r.category===state.filter)).sort((a,b)=>({Urgent:0,Medical:1,Administrative:2}[a.category]-{Urgent:0,Medical:1,Administrative:2}[b.category]));
 const selected=list.find(r=>r.id===state.selectedRequest)||list[0];
 const tones={Urgent:'red',Medical:'amber',Administrative:'gray'};
 const labels={Urgent:'Urgent review',Medical:'Medical review',Administrative:'Administrative'};
 return `<div class="intro"><div><p class="eyebrow">DOCTOR WORKSPACE · DR. NINA KOVAČ</p><h1>One request. The whole patient picture.</h1><p>Automatically assigned doctor requests, with medication details and the nurse’s recorded steps.</p></div><span class="step-label">${icon('inbox')} ${pending.length} awaiting review</span></div>
 <div class="doctor-layout"><section class="panel queue-panel"><div class="panel-head"><h2>Incoming requests</h2><span class="queue-count">${pending.length}</span></div><div class="filters" role="group" aria-label="Request category">${[['Pending','All'],['Urgent','Urgent'],['Medical','Medical'],['Completed','Completed']].map(([v,t])=>`<button class="filter ${state.filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${state.filter===v}">${t}${v==='Completed'?'':` · ${pending.filter(r=>v==='Pending'||r.category===v).length}`}</button>`).join('')}</div>
 ${list.map(r=>`<button class="queue-row ${selected?.id===r.id?'selected':''} ${r.category==='Urgent'?'urgent':''}" data-action="select-request" data-id="${e(r.id)}" aria-pressed="${selected?.id===r.id}"><div class="queue-patient"><strong>${e(state.patients[r.patient].name)}</strong><span class="pill ${r.status==='Pending'?tones[r.category]:'gray'}">${e(r.status==='Pending'?labels[r.category]:r.status)}</span></div><h3>${e(r.title)}</h3><p>${e(r.created)} · ${e(r.route)}</p></button>`).join('')||'<p class="empty">No requests in this category.</p>'}
 ${state.activity.length?`<div class="record-group"><h3>${icon('calendar')} Appointment updates</h3>${state.activity.slice(0,3).map(a=>`<div class="activity-row">${e(a.message)}<small>Demo scheduling activity</small></div>`).join('')}</div>`:''}
 <p class="context-line">Requests entered by patients appear here automatically. These are sample records.</p></section>
 <div class="stack" id="request-detail">${selected?detail(selected):'<section class="panel"><h2>Nothing to review here.</h2><p class="empty">Choose another category, or create a request in the patient version.</p></section>'}</div></div>`;
 function detail(r){const p=state.patients[r.patient];return `<section class="panel request-detail ${r.type==='Symptoms'?'decision-section':''}"><div class="panel-head"><div><p class="eyebrow">${e(state.patients[r.patient].name)} · ${e(r.type)}</p><h2>${e(r.title)}</h2></div><span class="pill ${tones[r.category]}">${labels[r.category]}</span></div>
 <div class="clinical-passport-strip"><strong>${icon('passport')} Patient Passport · ${e(p.name)}</strong><p><b>Allergies:</b> ${e(p.allergies.join(', '))}</p><div class="medicine-short-list"><b>Medications · select to inspect</b>${p.medications.map(m=>medicineLinkHTML(m,r.patient,{icon,escapeHTML:e})).join('')}</div><p><b>Previous operations:</b> ${e(p.operations.map(o=>o.name+' ('+o.date+')').join(' · '))}</p></div>
 ${r.type==='Symptoms'?`<div class="decision-preview"><h3>${icon('activity')} Decision-tree pathway</h3><div class="tree-path"><span class="tree-node">Patient’s choices</span>${icon('arrow')}<span class="tree-node">Automatically → ${e(r.route)}</span>${icon('arrow')}<span class="tree-node">Professional decision</span></div><p>The demo decision tree assigns the receiving professional automatically. These routing rules are illustrative, not clinically validated.</p></div>`:''}
 <div class="answer-list">${r.answers.map(([q,a])=>`<div class="answer-row"><span>${e(q)}</span><strong>${e(a)}</strong></div>`).join('')}</div>
 <p class="context-line">${icon('passport')} Patient Passport attached automatically. Nothing needs to be entered again.</p>
 ${r.status==='Pending'?`<div class="notice auto-route">${icon('checkCircle')}<span><strong>Automatically routed to ${e(r.route.toLowerCase())}</strong><br>The request’s type and questionnaire answers determine the receiving queue.</span></div><div class="doctor-actions">
 ${r.category==='Administrative'?`<button class="btn primary" data-action="complete-admin" data-id="${e(r.id)}">${icon('check')} Approve administrative request</button>`:
 r.type==='Tests'?`<button class="btn primary" data-action="review" data-id="${e(r.id)}" data-outcome="tests">${icon('check')} Review and approve test request</button><button class="btn" data-action="review" data-id="${e(r.id)}" data-outcome="consultation">${icon('calendar')} Consultation needed first</button>`:
 r.type==='Prescription'?`<button class="btn primary" data-action="review" data-id="${e(r.id)}" data-outcome="prescription">${icon('check')} Review and issue demo prescription</button><button class="btn" data-action="review" data-id="${e(r.id)}" data-outcome="consultation">${icon('calendar')} Medication review needed first</button>`:
 `<button class="btn primary" data-action="review" data-id="${e(r.id)}" data-outcome="${r.category==='Urgent'?'contact':'consultation'}">${icon(r.category==='Urgent'?'alert':'calendar')} ${r.category==='Urgent'?'Record urgent contact required':'Arrange a consultation'}</button>`}
 <p class="small muted">Actions update this demonstration only.</p></div>`:`<div class="status-response"><strong>${e(r.status)}</strong><p>${e(r.response||'Completed in this demo.')}</p></div>`}</section>${nursingRecordHTML(state,r.patient,{icon,escapeHTML:e})}${passportHTML(r.patient,true)}`;}
}
